import{_ as e,o as s,c as n,a0 as t}from"./chunks/framework.bcCluOOn.js";const g=JSON.parse('{"title":"AI Agents and AAYU","description":"","frontmatter":{},"headers":[],"relativePath":"guide/ai-agents.md","filePath":"guide/ai-agents.md"}'),o={name:"guide/ai-agents.md"};function p(i,a,l,r,u,d){return s(),n("div",null,[...a[0]||(a[0]=[t(`<h1 id="ai-agents-and-aayu" tabindex="-1">AI Agents and AAYU <a class="header-anchor" href="#ai-agents-and-aayu" aria-label="Permalink to &quot;AI Agents and AAYU&quot;">​</a></h1><p>AAYU&#39;s syntax is so close to natural language that large language models (LLMs) can generate high-quality, bug-free AAYU code almost effortlessly.</p><p>Because AAYU eliminates boilerplate, agents don&#39;t have to guess how your classes are structured or where your routing decorators go. They just read your intent and write the instructions.</p><h2 id="the-official-aayu-prompt" tabindex="-1">The Official AAYU Prompt <a class="header-anchor" href="#the-official-aayu-prompt" aria-label="Permalink to &quot;The Official AAYU Prompt&quot;">​</a></h2><p>If you want an AI agent to build an app for you, use this system prompt:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>You are an expert in the AAYU programming language.</span></span>
<span class="line"><span>AAYU is a natural-language inspired web programming language.</span></span>
<span class="line"><span>Generate production-ready code in AAYU based on the user&#39;s request.</span></span>
<span class="line"><span>Always use explicit keywords: task, guard, entity, map, serve, route.</span></span>
<span class="line"><span>Ensure every statement ends with a period (.).</span></span></code></pre></div><h2 id="examples-of-agent-generation" tabindex="-1">Examples of Agent Generation <a class="header-anchor" href="#examples-of-agent-generation" aria-label="Permalink to &quot;Examples of Agent Generation&quot;">​</a></h2><h3 id="claude-3-5-sonnet" tabindex="-1">Claude 3.5 Sonnet <a class="header-anchor" href="#claude-3-5-sonnet" aria-label="Permalink to &quot;Claude 3.5 Sonnet&quot;">​</a></h3><p><strong>Prompt:</strong> &quot;Build a simple AAYU web server that returns JSON data for a user profile.&quot;</p><p><strong>Agent Output:</strong></p><div class="language-aayu vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">aayu</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>serve on 3000.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>get &quot;/api/user&quot; to get_user.</span></span>
<span class="line"><span>    map user is {</span></span>
<span class="line"><span>        &quot;name&quot;: &quot;Alex&quot;,</span></span>
<span class="line"><span>        &quot;role&quot;: &quot;Admin&quot;,</span></span>
<span class="line"><span>        &quot;active&quot;: 1</span></span>
<span class="line"><span>    }.</span></span>
<span class="line"><span>    render json user.</span></span>
<span class="line"><span>end.</span></span></code></pre></div><h3 id="gpt-4o" tabindex="-1">GPT-4o <a class="header-anchor" href="#gpt-4o" aria-label="Permalink to &quot;GPT-4o&quot;">​</a></h3><p><strong>Prompt:</strong> &quot;Write a task to validate if a user&#39;s age is greater than 18.&quot;</p><p><strong>Agent Output:</strong></p><div class="language-aayu vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">aayu</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>task validate_age with age.</span></span>
<span class="line"><span>    if age is greater than 18.</span></span>
<span class="line"><span>        return 1.</span></span>
<span class="line"><span>    end.</span></span>
<span class="line"><span>    return 0.</span></span>
<span class="line"><span>end.</span></span></code></pre></div><h2 id="why-it-works-so-well" tabindex="-1">Why it works so well <a class="header-anchor" href="#why-it-works-so-well" aria-label="Permalink to &quot;Why it works so well&quot;">​</a></h2><p>LLMs are fundamentally trained on human text (English). By making the programming language itself closer to English, the &quot;translation gap&quot; between what the user asks for in English and what the AI has to output in code is drastically reduced.</p>`,17)])])}const h=e(o,[["render",p]]);export{g as __pageData,h as default};
